@startuml

class GasStation {
  + Address : string
}

class Pump {
  + CurrentLevel : double
  + ReorderingLevel : double
  + CriticalLevel : double
  + Status : string
}

class Gasoline {
  + Type : string
}

class Reservoir {
  + QuantityToOrder : double
}

class RefuelTurn {
  + Amount : double
  + DateTime : datetime
}

class Customer {
  + Status : string
  + Slack : int
}

class RefuelCard {
  + CardNumber : string
  + IsBlocked : boolean
}

class Invoice {
  + Month : string
  + Discount : double
  + Status : string
}

class Payment {
  + PaymentDate : date
}

GasStation "1" *-- "*" Pump
Pump "1" -- "1" Gasoline
Pump "1" -- "1" Reservoir
Pump "1" -- "0..1" RefuelTurn
Customer "0..1" -- "0..1" RefuelTurn
Customer "1" -- "0..*" RefuelCard
Customer "1" -- "0..*" Invoice
Invoice "1" -- "*" RefuelTurn
Invoice "1" -- "*" Payment

@enduml

